def backup(path):
 dest=REV/'before'/path.relative_to(ROOT);dest.parent.mkdir(parents=True,exist_ok=True)
 if not dest.exists():dest.write_bytes(path.read_bytes())

def esc(s):return s.replace('|',' / ').replace('\n',' ')
marker='### Main debates - live email review, 2026-11-01'
for tk,v in data.items():
 path=ROOT/'_wiki'/f'{tk}.md';s=path.read_text(encoding='utf-8-sig');backup(path)
 if marker in s:raise RuntimeError('Already applied '+tk)
 intro=marker+'\n\n_Priorities and falsifiers: Capstone synthesis, 2026-11-01, grounded in the dated emails below and the company evidence on this page. Bull/bear cases are analytical tests; they do not imply that every cited broker holds both views. Sales commentary and headline-only alerts retain their source labels._\n\n'
 table=['| Priority / investment question | Bull case | Bear case | Evidence that would resolve it | Sources |','|---|---|---|---|---|']
 for q,bull,bear,test,idx in v['rows']:table.append('| '+' | '.join([esc(q),esc(bull),esc(bear),esc(test),refs(idx,tk)])+' |')
 block=intro+'\n'.join(table)+'\n\n'
 s=s.replace('## Debate / thesis\n\n','## Debate / thesis\n\n'+block,1)
 note='### Live Outlook readout - recorded 2026-11-01\n\n'+v['note']+'\n\nSources: '+refs(v['indices'],tk)+'. Full connector-returned email bodies are archived; access to an email does not establish that its linked PDF/model was read. The original cached copies and older commentary below remain intact.\n\n'
 if tk=='KKR':
  note+='**Primary-source transaction check.** KKR\'s August 31 transaction presentation describes a $17bn agreement, approximately $3.3bn of after-tax proceeds and approximately $2.0bn of ANI, all conditional on closing. Aon\'s October 28 release still expected a Q4 close. These are transaction expectations, not a completed realization or recurring FRE. [KKR transaction presentation](../KKR/research/2026-08-31_USI_investor_presentation.md); [Aon announcement, 2026-08-31](../KKR/research/2026-08-31_USI_announcement.md); [Aon closing-status update, 2026-10-28](../KKR/research/2026-10-28_Aon_USI_status.md).\n\n'
 if tk=='APO':note+='Primary check: [Athene 8-K, 2026-10-05](../APO/research/2026-10-05_Athene_preliminary_alt_income.md). The filing expressly calls the estimates preliminary and unaudited. Existing Big Sky draw and fee timing is preserved in the [compute-deal timeline](themes/ai-compute-deals.md).\n\n'
 if tk=='BX':note+='The AI fee-recognition question is cross-referenced under existing **BX-GOOG-AVGO-2026** in the [compute-deal timeline](themes/ai-compute-deals.md); it adds no new commitment, draw or delivered capacity.\n\n'
